/* Segue DESIGN.md: cores calmas, contraste AA, alvos grandes, movimento curto. */
@font-face { font-family: 'Atkinson'; src: url('/fonts/atkinson-hyperlegible-400.woff2') format('woff2'); font-weight: 400; font-display: swap; }
@font-face { font-family: 'Atkinson'; src: url('/fonts/atkinson-hyperlegible-700.woff2') format('woff2'); font-weight: 700; font-display: swap; }

:root {
  /* Marca Gump: verde esmeralda + rosa rubi + pêssego sobre creme rosado. */
  --verde: #2E9E6B;
  --verde-forte: #1F7A50;
  --verde-claro: #EEF8F2;
  --rubi: #D9406E;
  --rubi-forte: #B8325A;
  --pessego: #FF9F6B;
  --pessego-claro: #FFE6D6;
  --papel: #FFF6F0;
  --cartao: #ffffff;
  --tinta: #1E3B2F;
  --suave: #55665D;
  --ok: var(--verde-forte);
  --alerta: #9A4A12;
  --erro: #A8324F;
  --borda: #EADBD0;
  --tema: var(--verde);
  --tema-fundo: var(--verde-claro);
  font-family: 'Atkinson', system-ui, sans-serif;
  color: var(--tinta);
  background: var(--papel);
  line-height: 1.5;
}

* { box-sizing: border-box; }
body { margin: 0; background: var(--papel); }
h1, h2 { line-height: 1.2; margin: 0 0 8px; }
h1 { font-size: 1.6rem; }
h2 { font-size: 1.2rem; }
a { color: var(--ok); }

button, .botao {
  font: inherit; font-weight: 700; color: var(--tinta);
  min-height: 48px; min-width: 48px; padding: 0 16px;
  border: 2px solid var(--tinta); border-radius: 10px; background: var(--cartao);
  cursor: pointer; text-decoration: none; display: inline-flex; align-items: center; justify-content: center;
  transition: transform 120ms ease;
}
button:active { transform: scale(0.97); }
button:disabled { opacity: 0.45; cursor: default; }
button.primario { background: var(--verde-forte); border-color: var(--verde-forte); color: #fff; }
button.primario:hover:not(:disabled) { background: var(--tinta); border-color: var(--tinta); }
button:focus-visible, .botao:focus-visible, input:focus-visible, select:focus-visible { outline: 3px solid var(--ok); outline-offset: 3px; }

input, select { font: inherit; min-height: 48px; padding: 0 12px; border: 2px solid var(--borda); border-radius: 10px; background: var(--cartao); color: var(--tinta); }
input[type='file'] { padding: 10px; }
label { display: flex; flex-direction: column; gap: 4px; font-weight: 700; }

.ajuda { color: var(--suave); margin: 4px 0; }
.erro { color: var(--erro); font-weight: 700; }
.linha { display: flex; flex-wrap: wrap; gap: 12px; align-items: flex-end; }
.linha.centro { justify-content: center; }

.cartao { background: var(--cartao); border: 1px solid var(--borda); border-radius: 16px; padding: 20px; }

/* Login: metade com a marca, metade com o formulário. */
.login { min-height: 100dvh; display: grid; grid-template-columns: 1fr 1fr; }
.login-marca { position: relative; overflow: hidden; background: var(--verde-claro); display: flex; flex-direction: column; justify-content: center; align-items: center; gap: 24px; padding: 48px 32px; text-align: center; }
.login-marca .logo, .login-frase { position: relative; }
.login-frase { margin: 0; max-width: 22ch; font-family: 'Fredoka', 'Atkinson', sans-serif; font-weight: 600; font-size: 1.7rem; line-height: 1.25; color: var(--tinta); }
.bolha { position: absolute; border-radius: 50%; }
.bolha.b1 { width: 340px; height: 340px; background: var(--pessego-claro); top: -110px; left: -120px; }
.bolha.b2 { width: 220px; height: 220px; background: #F6C9D6; bottom: -60px; right: -50px; }
.bolha.b3 { width: 90px; height: 90px; background: var(--pessego); bottom: 22%; left: 12%; opacity: 0.55; }
.login-form { display: grid; place-items: center; padding: 32px 16px; background: var(--papel); }
.login-form form { width: min(400px, 100%); display: flex; flex-direction: column; gap: 16px; }
.login-form h1 { font-family: 'Fredoka', 'Atkinson', sans-serif; font-size: 2rem; color: var(--tinta); }
.demo { border-top: 1px solid var(--borda); padding-top: 14px; }
.demo p { margin: 0 0 10px; color: var(--suave); }
.demo-botoes { display: flex; gap: 8px; flex-wrap: wrap; }
.demo-botoes button { border: none; flex: 1; }
.demo-verde { background: var(--verde-claro); color: var(--verde-forte); }
.demo-rubi { background: #FBE1E9; color: var(--rubi-forte); }
.demo-pessego { background: var(--pessego-claro); color: var(--alerta); }

/* Áreas de adulto */
.adulto { min-height: 100dvh; background: var(--papel); }
.cabecalho { display: flex; justify-content: space-between; align-items: center; gap: 12px 24px; flex-wrap: wrap; padding: 12px 24px; background: var(--verde-claro); border-bottom: 3px solid var(--verde); }
.cabecalho-marca { display: flex; align-items: center; gap: 14px; }
.cabecalho-titulo { padding: 4px 12px; border-radius: 999px; background: var(--cartao); color: var(--verde-forte); font-weight: 700; }
.cabecalho-meio { flex: 1; display: flex; justify-content: center; }
.cabecalho-acoes { display: flex; gap: 12px; align-items: center; }
.quem { color: var(--suave); }
.seletor-aluno { flex-direction: row; align-items: center; gap: 10px; }
.seletor-aluno span { color: var(--suave); }
.conteudo { max-width: 1040px; margin: 0 auto; padding: 28px 16px 64px; display: flex; flex-direction: column; gap: 20px; }

.aluno-topo { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; }
.aluno-topo > div { flex: 1; min-width: 180px; }
.aluno-topo h1 { font-family: 'Fredoka', 'Atkinson', sans-serif; font-size: 2.2rem; margin: 0; }
.aluno-topo .ajuda { margin: 0; }
.aluno-topo .botao { gap: 8px; }
.aluno-avatar { width: 72px; height: 72px; border-radius: 50%; display: grid; place-items: center; background: var(--pessego); color: var(--tinta); font-family: 'Fredoka', sans-serif; font-weight: 700; font-size: 2rem; border: 3px solid var(--cartao); box-shadow: 0 0 0 3px var(--pessego); }

.passos { list-style: none; margin: 0; padding: 16px 20px; display: flex; gap: 8px; background: var(--cartao); border-radius: 18px; border: 1px solid var(--borda); counter-reset: passo; }
.passos li { flex: 1; display: flex; align-items: center; gap: 10px; font-weight: 700; color: var(--suave); position: relative; }
.passos li:not(:last-child)::after { content: ''; flex: 1; height: 3px; border-radius: 3px; background: var(--borda); margin-left: 4px; }
.passos li.feito:not(:last-child)::after { background: var(--verde); }
.passo-marca { flex: none; width: 34px; height: 34px; border-radius: 50%; display: grid; place-items: center; background: #F3E9E1; color: var(--suave); }
.passos li.atual { color: var(--tinta); }
.passos li.atual .passo-marca { background: var(--pessego); color: var(--tinta); }
.passos li.feito { color: var(--verde-forte); }
.passos li.feito .passo-marca { background: var(--verde-forte); color: #fff; }

.bloco { background: var(--cartao); border: 1px solid var(--borda); border-radius: 20px; padding: 24px; display: flex; flex-direction: column; gap: 14px; }
.bloco h2 { font-family: 'Fredoka', 'Atkinson', sans-serif; font-size: 1.4rem; margin: 0; }
.bloco-titulo { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.nota-ia { display: inline-flex; align-items: center; gap: 6px; padding: 6px 12px; border-radius: 999px; background: var(--pessego-claro); color: var(--alerta); font-weight: 700; font-size: 0.95rem; }
.vazio { margin: 0; padding: 20px; border-radius: 14px; background: var(--papel); color: var(--suave); text-align: center; }

.envio { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; }
.soltar { width: 100%; cursor: pointer; display: flex; flex-direction: column; align-items: center; gap: 6px; text-align: center; padding: 28px 16px; border: 2px dashed var(--verde); border-radius: 16px; background: var(--verde-claro); font-weight: 400; }
.soltar:hover, .soltar:focus-within { background: #E2F3E9; }
.soltar:focus-within { outline: 3px solid var(--verde-forte); outline-offset: 3px; }
.soltar strong { font-size: 1.1rem; }
.soltar input { position: absolute; width: 1px; height: 1px; opacity: 0; }
.soltar-icone { width: 60px; height: 60px; border-radius: 50%; display: grid; place-items: center; background: var(--cartao); color: var(--verde-forte); }
.soltar.com-arquivo { border-style: solid; }

.grade-topicos { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 14px; }
.topico { padding: 18px; border-radius: 16px; display: flex; flex-direction: column; gap: 8px; }
.topico p { margin: 0; color: var(--tinta); font-size: 0.95rem; }
.topico-icone { width: 48px; height: 48px; border-radius: 14px; display: grid; place-items: center; background: var(--cartao); }
.cor-verde { background: var(--verde-claro); } .cor-verde .topico-icone, .sugestao-capa.cor-verde { color: var(--verde-forte); }
.cor-rubi { background: #FBE1E9; } .cor-rubi .topico-icone, .sugestao-capa.cor-rubi { color: var(--rubi-forte); }
.cor-pessego { background: var(--pessego-claro); } .cor-pessego .topico-icone, .sugestao-capa.cor-pessego { color: var(--alerta); }

.grade-cartoes-jogo { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 16px; }
.cartao-sugestao { border: 2px solid var(--borda); border-radius: 18px; overflow: hidden; display: flex; flex-direction: column; background: var(--cartao); }
.sugestao-capa { position: relative; height: 110px; display: grid; place-items: center; }
.sugestao-capa .selo { position: absolute; top: 10px; right: 10px; background: var(--cartao); }
.sugestao-corpo { padding: 16px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.sugestao-corpo strong { font-size: 1.15rem; }
.sugestao-corpo .ajuda { margin: 0; }
.sugestao-corpo .linha { margin-top: auto; padding-top: 8px; }
.sugestao-corpo button { gap: 6px; flex: 1; }
.cartao-sugestao.status-sugerido { border-color: var(--pessego); }
.cartao-sugestao.status-aprovado { border-color: var(--verde); }
.cartao-sugestao.status-recusado { opacity: 0.6; }
.aviso-acao { margin: 0; padding: 12px 16px; border-radius: 10px; background: var(--pessego-claro); color: var(--alerta); font-weight: 700; }

.etiquetas { list-style: none; padding: 0; margin: 8px 0; display: flex; flex-wrap: wrap; gap: 8px; }
.etiquetas li { padding: 6px 12px; border-radius: 999px; background: var(--verde-claro); color: var(--ok); font-weight: 700; }

.selo { font-size: 0.9rem; font-weight: 700; padding: 4px 10px; border-radius: 999px; background: #F3E9E1; }
.status-sugerido .selo { background: var(--pessego-claro); color: var(--alerta); }
.status-aprovado .selo { background: var(--verde-claro); color: var(--ok); }

.tabela { width: 100%; border-collapse: collapse; }
.tabela th, .tabela td { text-align: left; padding: 8px; border-bottom: 1px solid var(--borda); }
.barra { position: relative; display: inline-block; width: 140px; height: 20px; background: #F3E9E1; border-radius: 999px; overflow: hidden; vertical-align: middle; }
.barra span { display: block; height: 100%; background: var(--ok); }
.barra em { position: absolute; inset: 0; display: grid; place-items: center; font-style: normal; font-size: 0.8rem; font-weight: 700; color: var(--tinta); mix-blend-mode: normal; text-shadow: 0 0 3px var(--cartao); }

/* Área da criança: mesma estrutura em todos os temas, só os tokens mudam. */
.crianca { min-height: 100dvh; background: var(--tema-fundo); padding: 16px 16px 48px; font-size: 1.15rem; }
.crianca-topo { display: flex; justify-content: space-between; max-width: 880px; margin: 0 auto 16px; }
.crianca-bloco { max-width: 880px; margin: 0 auto 20px; background: var(--cartao); border-radius: 20px; padding: 24px; border: 2px solid color-mix(in srgb, var(--tema) 25%, transparent); }
.crianca button { min-height: 64px; border-color: var(--tema); }
.crianca button.primario { background: var(--tema); border-color: var(--tema); color: #fff; }
.emoji { font-size: 2.4rem; line-height: 1; }
.emoji.grande { font-size: 4.5rem; }
.avatar { display: flex; align-items: center; gap: 24px; }
.avatar > div { flex: 1; }
.xp { height: 24px; border-radius: 999px; background: var(--tema-fundo); overflow: hidden; margin: 8px 0 4px; }
.xp span { display: block; height: 100%; background: var(--tema); transition: width 300ms ease; }

.grade-temas, .grade-jogos { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 16px; margin-top: 16px; }
.tema, .cartao-jogo { flex-direction: column; gap: 8px; min-height: 140px !important; font-size: 1.15rem; background: var(--tema-fundo); }

.colecao { list-style: none; padding: 0; margin: 12px 0 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(72px, 1fr)); gap: 12px; }
.colecao li { aspect-ratio: 1; display: grid; place-items: center; font-size: 2.2rem; border-radius: 16px; }
.colecao .ganho { background: var(--tema-fundo); }
.colecao .bloqueado { background: #F3E9E1; color: var(--suave); font-size: 1.6rem; }

.jogo-area { text-align: center; display: flex; flex-direction: column; align-items: center; gap: 12px; }
button.grande { min-height: 72px; padding: 0 28px; font-size: 1.2rem; }

.fundo-dialogo { position: fixed; inset: 0; background: rgba(31, 42, 46, 0.45); display: grid; place-items: center; padding: 16px; }
.dialogo { background: var(--papel); border: 3px solid var(--tinta); border-radius: 16px; padding: 24px; max-width: 380px; width: 100%; text-align: center; }
.dialogo p { font-weight: 700; font-size: 1.3rem; margin: 0 0 20px; }

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}

@media (max-width: 760px) {
  .passos { flex-direction: column; align-items: stretch; }
  .passos li:not(:last-child)::after { display: none; }
  .cabecalho-meio { order: 3; flex-basis: 100%; justify-content: flex-start; }
  .login { grid-template-columns: 1fr; grid-template-rows: auto 1fr; }
  .login-marca { padding: 32px 16px; gap: 12px; }
  .login-marca .logo { font-size: 48px !important; }
  .login-frase { font-size: 1.25rem; }
}

@media (max-width: 600px) {
  .avatar { flex-direction: column; text-align: center; }
  .tabela { font-size: 0.9rem; }
  .barra { width: 90px; }
}

/* Logo do Gump */
.logo { display: inline-flex; align-items: center; gap: 0.1em; font-family: 'Fredoka', 'Atkinson', sans-serif; font-weight: 700; color: #2E9E6B; letter-spacing: -0.02em; line-height: 1; }
.logo img { height: 1.45em; width: auto; }
// Temas de hiperfoco: trocam só cor, personagem e itens da coleção.
// Layout, botões, fluxo e XP são iguais em todos (DESIGN.md, regra 8).
// Os emojis são provisórios até termos as ilustrações.
export const TEMAS = [
  {
    id: 'trem',
    nome: 'Trem',
    personagem: '🚂',
    cor: '#3d6b56',
    fundo: '#e8efe9',
    itens: ['🚂', '🚃', '🚄', '🚇', '🚋', '🚉'],
  },
  {
    id: 'dinossauro',
    nome: 'Dinossauro',
    personagem: '🦕',
    cor: '#5f6b3a',
    fundo: '#eef0e2',
    itens: ['🦕', '🦖', '🥚', '🌋', '🌿', '🦴'],
  },
  {
    id: 'aviao',
    nome: 'Avião',
    personagem: '✈️',
    cor: '#3b5f7a',
    fundo: '#e6edf2',
    itens: ['✈️', '🛩️', '🚁', '🛫', '🪂', '🌤️'],
  },
  {
    id: 'navio',
    nome: 'Navio',
    personagem: '🚢',
    cor: '#2f5d6b',
    fundo: '#e4eef0',
    itens: ['🚢', '⛵', '🛥️', '⚓', '🧭', '🐋'],
  },
]

export const temaPorId = (id) => TEMAS.find((t) => t.id === id) ?? null

