import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { api } from '../api.js'
import { TEMAS, temaPorId } from '../temas.js'

const XP_POR_ITEM = 20 // igual a site/server/src/regras.js

// Aplica as cores do tema como tokens; a estrutura da tela não muda.
export function estiloTema(tema) {
  return tema ? { '--tema': tema.cor, '--tema-fundo': tema.fundo } : undefined
}

function EscolherTema({ escolher }) {
  return (
    <section className="crianca-bloco">
      <h1>Do que você mais gosta?</h1>
      <div className="grade-temas">
        {TEMAS.map((t) => (
          <button key={t.id} className="tema" style={estiloTema(t)} onClick={() => escolher(t.id)}>
            <span className="emoji" aria-hidden="true">{t.personagem}</span>
            {t.nome}
          </button>
        ))}
      </div>
    </section>
  )
}

export default function Crianca({ usuario, sair }) {
  const [dados, setDados] = useState(null)
  const [trocando, setTrocando] = useState(false)
  const [erro, setErro] = useState('')
  const navegar = useNavigate()

  useEffect(() => {
    api(`/alunos/${usuario.aluno_id}`).then(setDados).catch((e) => setErro(e.message))
  }, [usuario.aluno_id])

  async function escolher(hiperfoco) {
    const aluno = await api(`/alunos/${usuario.aluno_id}/hiperfoco`, { metodo: 'PATCH', corpo: { hiperfoco } })
    setDados((d) => ({ ...d, aluno }))
    setTrocando(false)
  }

  const tema = temaPorId(dados?.aluno.hiperfoco)
  const desbloqueados = tema ? Math.min(Math.floor((dados.xp ?? 0) / XP_POR_ITEM), tema.itens.length) : 0
  const progresso = ((dados?.xp ?? 0) % XP_POR_ITEM) / XP_POR_ITEM

  return (
    <div className="crianca" style={estiloTema(tema)}>
      <header className="crianca-topo">
        <button onClick={sair}>Sair</button>
        {tema && !trocando && <button onClick={() => setTrocando(true)}>Trocar tema</button>}
      </header>

      {erro && <p className="erro" role="alert">{erro}</p>}

      {dados && (!tema || trocando) && <EscolherTema escolher={escolher} />}

      {dados && tema && !trocando && (
        <>
          <section className="crianca-bloco avatar">
            <span className="emoji grande" aria-hidden="true">{tema.personagem}</span>
            <div>
              <h1>Oi, {dados.aluno.nome}!</h1>
              <div className="xp" role="progressbar" aria-valuemin={0} aria-valuemax={XP_POR_ITEM} aria-valuenow={dados.xp % XP_POR_ITEM} aria-label="XP até o próximo item">
                <span style={{ width: `${progresso * 100}%` }} />
              </div>
              <p>⭐ {dados.xp} XP</p>
            </div>
          </section>

          <section className="crianca-bloco">
            <h2>🎮 Seus jogos</h2>
            {dados.jogos.length ? (
              <div className="grade-jogos">
                {dados.jogos.map((j) => (
                  <button key={j.id} className="cartao-jogo" onClick={() => navegar(`/crianca/jogo/${j.id}`)}>
                    <span className="emoji" aria-hidden="true">▶️</span>
                    {j.nome}
                  </button>
                ))}
              </div>
            ) : (
              <p>Logo seus jogos vão aparecer aqui. 🙂</p>
            )}
          </section>

          <section className="crianca-bloco">
            <h2>🏆 Sua coleção</h2>
            <ul className="colecao">
              {tema.itens.map((item, i) => (
                <li key={item} className={i < desbloqueados ? 'ganho' : 'bloqueado'} aria-label={i < desbloqueados ? 'Item ganho' : 'Item ainda não ganho'}>
                  {i < desbloqueados ? item : '?'}
                </li>
              ))}
            </ul>
          </section>
        </>
      )}
    </div>
  )
}
import { useState } from 'react'
import { api } from '../api.js'
import Logo from './Logo.jsx'

const DEMO = [
  { rotulo: 'Escola', email: 'escola@demo.com', cor: 'verde' },
  { rotulo: 'Família', email: 'familia@demo.com', cor: 'rubi' },
  { rotulo: 'Criança', email: 'ana@demo.com', cor: 'pessego' },
]

export default function Login({ entrar }) {
  const [email, setEmail] = useState('')
  const [senha, setSenha] = useState('')
  const [erro, setErro] = useState('')
  const [enviando, setEnviando] = useState(false)

  async function enviar(ev) {
    ev.preventDefault()
    setErro('')
    setEnviando(true)
    try {
      const { usuario } = await api('/login', { metodo: 'POST', corpo: { email, senha } })
      entrar(usuario)
    } catch (e) {
      setErro(e.message)
    } finally {
      setEnviando(false)
    }
  }

  return (
    <main className="login">
      <section className="login-marca">
        <span className="bolha b1" aria-hidden="true" />
        <span className="bolha b2" aria-hidden="true" />
        <span className="bolha b3" aria-hidden="true" />
        <Logo tamanho={72} />
        <p className="login-frase">Do PDI ao jogo, no ritmo de cada criança.</p>
      </section>

      <section className="login-form">
        <form onSubmit={enviar}>
          <h1>Entrar</h1>
          <label>
            E-mail
            <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} required autoComplete="username" />
          </label>
          <label>
            Senha
            <input type="password" value={senha} onChange={(e) => setSenha(e.target.value)} required autoComplete="current-password" />
          </label>
          {erro && <p className="erro" role="alert">{erro}</p>}
          <button className="primario" disabled={enviando}>{enviando ? 'Entrando…' : 'Entrar'}</button>

          <div className="demo">
            <p>Contas de demonstração (senha <code>demo</code>):</p>
            <div className="demo-botoes">
              {DEMO.map((d) => (
                <button type="button" key={d.email} className={`demo-${d.cor}`} onClick={() => { setEmail(d.email); setSenha('demo') }}>
                  {d.rotulo}
                </button>
              ))}
            </div>
          </div>
        </form>
      </section>
    </main>
  )
}
import Logo from './Logo.jsx'

// Cabeçalho das áreas de adulto (escola e pais). `children` entra no meio (ex.: escolha do aluno).
export default function Cabecalho({ usuario, sair, titulo, children }) {
  return (
    <header className="cabecalho">
      <div className="cabecalho-marca">
        <Logo tamanho={28} />
        <span className="cabecalho-titulo">{titulo}</span>
      </div>
      {children && <div className="cabecalho-meio">{children}</div>}
      <div className="cabecalho-acoes">
        <span className="quem">{usuario.nome}</span>
        <button onClick={sair}>Sair</button>
      </div>
    </header>
  )
}
// Logo do Gump: beija-flor (public/gump-beija-flor.svg) + nome em Fredoka.
export default function Logo({ tamanho = 48 }) {
  return (
    <span className="logo" style={{ fontSize: tamanho }}>
      <img src="/gump-beija-flor.svg" alt="" aria-hidden="true" />
      <span>gump</span>
    </span>
  )
}
// Ícones de traço das áreas de adulto (sem emoji, conforme DESIGN.md).
const CAMINHOS = {
  envio: 'M12 16V4m0 0-5 5m5-5 5 5M4 16v3a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-3',
  documento: 'M7 3h7l5 5v12a1 1 0 0 1-1 1H7a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1Zm7 0v5h5M9 13h6M9 17h4',
