// Prints das telas sem escrever no banco: respostas de /api/alunos/ana interceptadas.
import { chromium } from 'playwright'
const BASE = 'http://127.0.0.1:5180'
const OUT = process.argv[2]
const browser = await chromium.launch()

async function pagina(usuario, { largura = 1280, altura = 900, hiperfoco, xp } = {}) {
  const ctx = await browser.newContext({ viewport: { width: largura, height: altura } })
  if (usuario) await ctx.addInitScript((u) => localStorage.setItem('dopamine-usuario', JSON.stringify(u)), usuario)
  const p = await ctx.newPage()
  p.on('pageerror', (e) => console.log('ERRO', e.message))
  if (hiperfoco !== undefined || xp !== undefined) {
    await p.route(/\/api\/alunos\/ana$/, async (rota) => {
      if (rota.request().method() !== 'GET') return rota.continue()
      const r = await rota.fetch()
      const j = await r.json()
      if (hiperfoco !== undefined) j.aluno.hiperfoco = hiperfoco
      if (xp !== undefined) j.xp = xp
      await rota.fulfill({ response: r, json: j })
    })
  }
  return p
}
const ANA = { id: 'crianca-1', nome: 'Ana', perfil: 'crianca', aluno_id: 'ana' }
const FAM = { id: 'resp-1', nome: 'Família da Ana', perfil: 'responsavel', aluno_id: 'ana' }
const ESC = { id: 'escola-1', nome: 'Escola', perfil: 'escola' }

const shot = async (p, nome, full = true) => { await p.waitForTimeout(700); await p.screenshot({ path: `${OUT}/${nome}.png`, fullPage: full }) }

let p = await pagina(null)
await p.goto(BASE); await shot(p, '01-login')
await p.getByRole('button', { name: /Família/ }).click(); await shot(p, '02-login-familia')

for (const [tema, xp] of [['trem', 50], ['aviao', 30], ['dinossauro', 10], ['aranha', 70]]) {
  p = await pagina(ANA, { hiperfoco: tema, xp })
  await p.goto(`${BASE}/crianca`); await shot(p, `10-crianca-${tema}`)
}
p = await pagina(ANA, { hiperfoco: null })
await p.goto(`${BASE}/crianca`); await shot(p, '11-escolher-tema')
p = await pagina(ANA, { hiperfoco: 'trem', xp: 50, largura: 390, altura: 844 })
await p.goto(`${BASE}/crianca`); await shot(p, '12-crianca-celular')
p = await pagina(ANA, { hiperfoco: 'trem', xp: 50 })
await p.goto(`${BASE}/crianca/jogo/memoria`); await shot(p, '13-jogo-antes', false)

p = await pagina(FAM)
await p.goto(`${BASE}/pais`); await shot(p, '20-familia')
p = await pagina(ESC)
await p.goto(`${BASE}/escola`); await shot(p, '30-escola')
await p.goto(`${BASE}/escola/desempenho/ana`); await shot(p, '31-desempenho')
await browser.close()

